import math

def calculate(expr: str) -> float:
    # WARNING: example of an insecure pattern for discussion
    return eval(expr, {"__builtins__": {}}, {"sqrt": math.sqrt})

def calculate_pow(base: int, exp: int) -> int:
    return base ** exp   # unbounded: user could pass exp=10**9

import ast, operator

ALLOWED = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
           ast.Div: operator.truediv, ast.Pow: operator.pow, ast.USub: operator.neg}

def safe_eval(expr: str):
    tree = ast.parse(expr, mode="eval")
    def _eval(node):
        if isinstance(node, ast.Expression):   return _eval(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)): return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in ALLOWED:
            return ALLOWED[type(node.op)](_eval(node.left), _eval(node.right))
        if isinstance(node, ast.UnaryOp) and type(node.op) in ALLOWED:
            return ALLOWED[type(node.op)](_eval(node.operand))
        raise ValueError("Disallowed expression")
    return _eval(tree)

def calculate(expr: str):
    # DANGEROUS: direct eval of untrusted input
    return eval(expr)

