def _walk(node, variables, depth=0):
    if depth > 20:
        raise ValueError("expression nested too deeply")
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.Name) and node.id in variables:
        return variables[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in ALLOWED_OPS:
        left = _walk(node.left, variables, depth + 1)
        right = _walk(node.right, variables, depth + 1)
        if isinstance(node.op, ast.Pow) and abs(right) > 1000:
            raise ValueError("exponent too large")
        return _apply(node.op, left, right)
    raise ValueError(f"disallowed syntax: {type(node).__name__}")

import ast, operator

_BIN_OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}

def evaluate(expr: str):
    tree = ast.parse(expr, mode="eval")
    return _eval(tree.body)

def _eval(node):
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.BinOp):
        return _BIN_OPS[type(node.op)](_eval(node.left), _eval(node.right))
    raise ValueError("unsupported node")

import operator
import ast

ALLOWED_OPS = {ast.Add: operator.add, ast.Sub: operator.sub,
               ast.Mult: operator.mul, ast.Div: operator.truediv,
               ast.Mod: operator.mod, ast.Pow: operator.pow}
MAX_LEN = 256
MAX_DEPTH = 20

def evaluate(expr: str):
    if not isinstance(expr, str) or len(expr) > MAX_LEN:
        raise ValueError("invalid input")
    tree = ast.parse(expr, mode="eval")
    return _eval(tree.body, 0)

def _eval(node, depth):
    if depth > MAX_DEPTH:
        raise ValueError("expression too deep")
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in ALLOWED_OPS:
        return ALLOWED_OPS[type(node.op)](_eval(node.left, depth+1), _eval(node.right, depth+1))
    raise ValueError("disallowed expression")

def calculate(expr: str):
    # ACCEPTED: raw user input straight into eval
    return eval(expr)

def rules_engine(condition: str, data: dict):
    return eval(condition, {}, data)
